1	export type QuoteResult = { premium: number };
2	
3	export type ScenarioResults = { results: QuoteResult[] };
4	
5	const PROCESSING_FEE = 5;
6	
7	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
8	
9	const ITEM_BASE_PREMIUM: Record<string, number> = {
10	  sword: 100,
11	  amulet: 60,
12	  staff: 80,
13	  potion: 40,
14	  rune: 25,
15	  moonstone: 25,
16	};
17	
18	type Item = { type: string };
19	
20	type Step = { op: string; items: Item[] };
21	
22	type Scenario = { customer: { yearsWithMHPCO: number }; steps: Step[] };
23	
24	const BLOCK_SIZE = 3;
25	
26	// A block is exactly BLOCK_SIZE components of the same type, priced as a unit.
27	// Exactly: 4 runes are not a block (4 x 25), and 2 runes + 1 moonstone is not
28	// a block either — "alike" means the same type, not the same family.
29	const BLOCK_BASE_PREMIUM = 60;
30	
31	const COMPONENT_TYPES = ["rune", "moonstone"];
32	
33	const countByType = (items: Item[]): Map<string, number> => {
34	  const counts = new Map<string, number>();
35	  for (const item of items) {
36	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
37	  }
38	  return counts;
39	};
40	
41	const groupBasePremium = (type: string, count: number): number => {
42	  if (COMPONENT_TYPES.includes(type) && count === BLOCK_SIZE) {
43	    return BLOCK_BASE_PREMIUM;
44	  }
45	
46	  return count * ITEM_BASE_PREMIUM[type];
47	};
48	
49	const policyBasePremium = (items: Item[]): number => {
50	  let total = 0;
51	  for (const [type, count] of countByType(items)) {
52	    total += groupBasePremium(type, count);
53	  }
54	  return total;
55	};
56	
57	const quoteStep = (step: Step): QuoteResult => {
58	  const basePremium = policyBasePremium(step.items);
59	  // Deliberately additive, not `base * (1 + rate)`: the latter is the same in
60	  // exact arithmetic but not in binary floating point (100 * 1.1 is
61	  // 110.00000000000001), and Math.ceil turns that 1e-14 into a whole gold piece.
62	  const afterPercentageModifiers =
63	    basePremium + basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
64	
65	  // The fee is added after every percentage modifier, and only the final
66	  // premium is rounded — intermediates stay fractional.
67	  return { premium: Math.ceil(afterPercentageModifiers + PROCESSING_FEE) };
68	};
69	
70	export const runScenario = (scenario: Scenario): ScenarioResults => ({
71	  results: scenario.steps.map(quoteStep),
72	});
73

